exercise.solution:
const { useState } = React;

const tasks = [
  { id: 1, title: 'Prepare weekly report', done: false },
  { id: 2, title: 'Review project report', done: true },
  { id: 3, title: 'Fix login bug', done: false },
  { id: 4, title: 'Update documentation', done: true },
  { id: 5, title: 'Plan customer meeting', done: false },
];

function App() {
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('all');

  const filteredTasks = tasks.filter((task) => {
    const matchesSearch = task.title.toLowerCase().includes(search.trim().toLowerCase());
    const matchesStatus =
      status === 'all' ||
      (status === 'done' && task.done) ||
      (status === 'open' && !task.done);

    return matchesSearch && matchesStatus;
  });

  return (
    <main>
      <h1>Task filter</h1>

      <label htmlFor="search">Search tasks</label>
      <input
        id="search"
        type="text"
        value={search}
        onChange={(event) => setSearch(event.target.value)}
      />

      <label htmlFor="status">Status</label>
      <select
        id="status"
        value={status}
        onChange={(event) => setStatus(event.target.value)}
      >
        <option value="all">all</option>
        <option value="open">open</option>
        <option value="done">done</option>
      </select>

      <p role="status">
        {filteredTasks.length === 0
          ? 'No tasks match'
          : `${filteredTasks.length} ${filteredTasks.length === 1 ? 'task' : 'tasks'}`}
      </p>

      <ul aria-label="Tasks">
        {filteredTasks.map((task) => (
          <li key={task.id}>{task.title}</li>
        ))}
      </ul>
    </main>
  );
}

