const search = document.querySelector('label[for="search"] + input');
const status = document.querySelector('label[for="status"] + select');
const list = document.querySelector('ul[aria-label="Tasks"]');
const items = [...list.querySelectorAll('li')];

if (!search || search.getAttribute('type') !== 'text') throw new Error('Search input is missing');
if (!status) throw new Error('Status select is missing');
if (status.querySelectorAll('option').length !== 3) throw new Error('Expected three status options');
if (items.length !== 5) throw new Error('Expected all five tasks initially');
if (document.querySelector('[role="status"]').textContent.trim() !== '5 tasks') throw new Error('Expected 5 tasks status');

const input = document.querySelector('label[for="search"] + input');
if (!input) throw new Error('Search input is missing');

await typeInto(input, 'report');
await tick();

const items = [...document.querySelector('ul[aria-label="Tasks"]').querySelectorAll('li')].map((li) => li.textContent.trim());
if (items.length !== 2) throw new Error(`Expected 2 report tasks, got ${items.length}`);
if (!items.every((title) => title.toLowerCase().includes('report'))) throw new Error('A non-report task was rendered');
if (document.querySelector('[role="status"]').textContent.trim() !== '2 tasks') throw new Error('Expected 2 tasks status');

const select = document.querySelector('label[for="status"] + select');
if (!select) throw new Error('Status select is missing');

select.value = 'done';
select.dispatchEvent(new Event('change', { bubbles: true }));
await tick();

const items = [...document.querySelector('ul[aria-label="Tasks"]').querySelectorAll('li')].map((li) => li.textContent.trim());
const expected = ['Review project report', 'Update documentation'];
if (items.length !== expected.length) throw new Error(`Expected ${expected.length} completed tasks, got ${items.length}`);
for (const title of expected) {
  if (!items.includes(title)) throw new Error(`Missing completed task: ${title}`);
}
if (document.querySelector('[role="status"]').textContent.trim() !== '2 tasks') throw new Error('Expected 2 tasks status');

