await tick();

const items = [...document.querySelector('ul[aria-label="Tasks"]').querySelectorAll('li')].map((li) => li.textContent.trim());
if (items.length !== 1) throw new Error(`Expected one completed report, got ${items.length}`);
if (items[0] !== 'Review project report') throw new Error('Wrong task remained after combining filters');
if (document.querySelector('[role="status"]').textContent.trim() !== '1 task') throw new Error('Expected singular 1 task status');

